def format_fraction_as_mixed(numerator, denominator):
    import math
    whole = numerator // denominator
    rem = numerator % denominator
    if rem == 0:
        return str(whole)
    g = math.gcd(rem, denominator)
    rem //= g
    denominator //= g
    if whole == 0:
        return f"{rem}/{denominator}"
    return f"{whole} {rem}/{denominator}"

def kth_largest_distinct(lst, k):
    distinct = sorted(set(lst), reverse=True)
    if k < 1 or k > len(distinct):
        return None
    return distinct[k - 1]

def is_balanced_brackets(tokens):
    depth = 0
    for t in tokens:
        if t == '(':
            depth += 1
        else:
            depth -= 1
        if depth < 0:
            return False
    return depth == 0

def clip_lines(text, maxlines):
    lines = text.split('\n')
    if len(lines) <= maxlines:
        return '\n'.join(lines)
    return '\n'.join(lines[:maxlines] + ['...'])

def is_valid_wildcard_mask(s):
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p.isdigit() or int(p) > 255:
            return False
    bits = ''.join(format(int(p), '08b') for p in parts)
    ones = bits.find('1')
    if ones == -1:
        return True
    return '0' not in bits[ones:]

def sum_of_digit_factorials(n):
    def fact(k):
        r = 1
        for i in range(2, k + 1):
            r *= i
        return r
    return sum(fact(int(d)) for d in str(abs(n)))

