def slugify_maxlen(s, maxlen):
    import re
    slug = re.sub(r'-{2,}', '-', re.sub(r'[^a-z0-9]+', '-', s.lower().strip())).strip('-')
    if len(slug) <= maxlen:
        return slug
    truncated = slug[:maxlen]
    if '-' in truncated:
        truncated = truncated[:truncated.rfind('-')]
    return truncated.strip('-')

