def is_valid_tag_sequence(s):
    import re
    tokens = re.findall(r'</?[a-z]+>|.', s)
    stack = []
    for tok in tokens:
        m_open = re.fullmatch(r'<([a-z]+)>', tok)
        m_close = re.fullmatch(r'</([a-z]+)>', tok)
        if m_open:
            stack.append(m_open.group(1))
        elif m_close:
            if not stack or stack[-1] != m_close.group(1):
                return False
            stack.pop()
        else:
            return False
    return len(stack) == 0

def swap_case_custom(s):
    out = []
    for ch in s:
        if ch.isupper():
            out.append(ch.lower())
        elif ch.islower():
            out.append(ch.upper())
        else:
            out.append(ch)
    return ''.join(out)

def is_valid_ipv4_address(s):
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p.isdigit():
            return False
        if len(p) > 1 and p[0] == '0':
            return False
        if int(p) > 255:
            return False
    return True

